function minimumMoves(arr) {
  const n = arr.length;
  // dp[i][j] is the fewest moves that clear arr[i..j]; empty ranges are never written and stay 0.
  const dp = Array.from({ length: n + 1 }, () => new Array(n).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    for (let j = i; j < n; j++) {
      let best = 1 + dp[i + 1][j];
      if (i + 1 <= j && arr[i] === arr[i + 1]) {
        best = Math.min(best, 1 + dp[i + 2][j]);
      }
      for (let k = i + 2; k <= j; k++) {
        if (arr[i] === arr[k]) {
          best = Math.min(best, dp[i + 1][k - 1] + dp[k + 1][j]);
        }
      }
      dp[i][j] = best;
    }
  }
  return dp[0][n - 1];
}

