function minimumMoves(arr) {
  // Try every palindromic block to delete, on every array that can arise, remembering results by contents.
  const memo = new Map();
  const isPalindrome = (list, from, to) => {
    while (from < to) {
      if (list[from] !== list[to]) return false;
      from++;
      to--;
    }
    return true;
  };
  const solve = list => {
    if (list.length === 0) return 0;
    const key = list.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = Infinity;
    for (let from = 0; from < list.length; from++) {
      for (let to = from; to < list.length; to++) {
        if (isPalindrome(list, from, to)) best = Math.min(best, 1 + solve([...list.slice(0, from), ...list.slice(to + 1)]));
      }
    }
    memo.set(key, best);
    return best;
  };
  return solve(arr);
}

