function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 8);
  // Few distinct values make long palindromes and shared ends likely; sometimes use the full range.
  const top = rand() < 0.7 ? 1 + Math.floor(rand() * 3) : 20;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
